// Some portions generated by Codex
package org.eclipse.rdf4j.common.net;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.net.InetAddress;
import java.net.URI;
import java.net.UnknownHostException;

import org.junit.jupiter.api.Test;

class PublicNetworkAccessPolicyTest {

	@Test
	void rejectsNonGlobalIpv4AddressClasses() throws Exception {
		PublicNetworkAccessPolicy policy = policyResolvingTo("8.8.8.8");

		for (String address : new String[] {
				"0.0.0.0", "10.0.0.1", "100.64.0.1", "127.0.0.1", "169.254.1.1", "172.16.0.1",
				"192.0.0.1", "192.0.2.1", "192.88.99.1", "192.168.1.1", "198.18.0.1", "198.51.100.1",
				"203.0.113.1", "224.0.0.1", "240.0.0.1", "255.255.255.255" }) {
			assertDenied(policy, "http://" + address + "/resource");
		}
	}

	@Test
	void rejectsNonGlobalIpv6AddressClassesAndMappedPrivateIpv4() throws Exception {
		PublicNetworkAccessPolicy policy = policyResolvingTo("2606:4700:4700::1111");

		for (String address : new String[] {
				"::", "::1", "::ffff:127.0.0.1", "64:ff9b:1::1", "100::1", "100:0:0:1::1", "2001::1",
				"2001:2::1", "2001:db8::1", "2002::1", "3fff::1", "5f00::1", "fc00::1", "fe80::1",
				"ff00::1" }) {
			assertDenied(policy, "http://[" + address + "]/resource");
		}
	}

	@Test
	void permitsGloballyReachableAddressesIncludingRegistryExceptions() throws Exception {
		PublicNetworkAccessPolicy policy = policyResolvingTo("8.8.8.8");

		for (String target : new String[] {
				"http://8.8.8.8/", "http://192.0.0.9/", "http://192.31.196.1/", "http://192.52.193.1/",
				"http://192.175.48.1/", "http://[64:ff9b::808:808]/", "http://[2001:1::1]/",
				"http://[2001:3::1]/", "http://[2001:4:112::1]/", "http://[2001:20::1]/",
				"http://[2001:30::1]/", "http://[2606:4700:4700::1111]/" }) {
			assertThatCode(() -> policy.checkInitial(URI.create(target))).doesNotThrowAnyException();
		}
	}

	@Test
	void rejectsMixedPublicAndPrivateDnsAnswers() throws Exception {
		PublicNetworkAccessPolicy policy = new PublicNetworkAccessPolicy(host -> addresses("8.8.8.8", "10.0.0.1"),
				null, null);

		assertDenied(policy, "https://example.org/resource");
	}

	@Test
	void exactHostnameIpAndCidrExceptionsAreNarrow() throws Exception {
		PublicNetworkAccessPolicy policy = new PublicNetworkAccessPolicy(host -> addresses("10.20.30.40"),
				"internal.example,127.0.0.1", "192.168.0.0/16,fd00::/8");

		assertThatCode(() -> policy.checkInitial(URI.create("https://internal.example/"))).doesNotThrowAnyException();
		assertThatCode(() -> policy.checkInitial(URI.create("http://127.0.0.1/"))).doesNotThrowAnyException();
		assertThatCode(() -> policy.checkInitial(URI.create("http://192.168.255.255/"))).doesNotThrowAnyException();
		assertThatCode(() -> policy.checkInitial(URI.create("http://[fdff::1]/"))).doesNotThrowAnyException();
		assertDenied(policy, "http://172.16.0.1/");
	}

	@Test
	void rejectsInvalidUriFormsAndHttpsDowngrades() throws Exception {
		PublicNetworkAccessPolicy policy = policyResolvingTo("8.8.8.8");

		for (String target : new String[] {
				"file:///tmp/data.ttl", "ftp://example.org/data.ttl", "http://user:password@example.org/",
				"http:///missing-host", "/relative", "http://example.org:0/" }) {
			assertDenied(policy, target);
		}
		assertThatThrownBy(() -> policy.checkRedirect(
				URI.create("https://example.org/one"), URI.create("http://example.org/two")))
						.isInstanceOf(java.io.IOException.class)
						.hasMessageContaining("must not downgrade");
	}

	@Test
	void invalidAllowlistConfigurationFailsClosed() {
		HostnameResolver resolver = host -> addresses("8.8.8.8");

		assertThatThrownBy(() -> new PublicNetworkAccessPolicy(resolver, "*.example.org", null))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> new PublicNetworkAccessPolicy(resolver, null, "10.0.0.0/99"))
				.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> new PublicNetworkAccessPolicy(resolver, "example.org,", null))
				.isInstanceOf(IllegalArgumentException.class);
	}

	private static PublicNetworkAccessPolicy policyResolvingTo(String... addresses) {
		return new PublicNetworkAccessPolicy(host -> addresses(addresses), null, null);
	}

	private static InetAddress[] addresses(String... addresses) throws UnknownHostException {
		InetAddress[] result = new InetAddress[addresses.length];
		for (int i = 0; i < addresses.length; i++) {
			result[i] = InetAddress.getByName(addresses[i]);
		}
		return result;
	}

	private static void assertDenied(PublicNetworkAccessPolicy policy, String target) {
		assertThatThrownBy(() -> policy.checkInitial(URI.create(target)))
				.isInstanceOf(java.io.IOException.class)
				.hasMessageStartingWith("Remote resource access denied:");
	}
}
